using Xunit;

public class U16GUITest
{
    [Fact]
    public void TestPEEPAdjustment()
    {
        // Arrange
        var gui = new GUI();

        // Act
        gui.AdjustPEEP(10);

        // Assert
        Assert.Equal(10, gui.PEEP);
    }

    [Fact]
    public void TestRRAdjustment()
    {
        // Arrange
        var gui = new GUI();

        // Act
        gui.AdjustRR(20);

        // Assert
        Assert.Equal(20, gui.RR);
    }

    [Fact]
    public void TestIERAdjustment()
    {
        // Arrange
        var gui = new GUI();

        // Act
        gui.AdjustIER(1.2);

        // Assert
        Assert.Equal(1.2, gui.IER);
    }

    [Fact]
    public void TestO2InfusionAdjustment()
    {
        // Arrange
        var gui = new GUI();

        // Act
        gui.AdjustO2Infusion(0.8);

        // Assert
        Assert.Equal(0.8, gui.O2Infusion);
    }

    [Fact]
    public void TestHFNCFlowRateAdjustment()
    {
        // Arrange
        var gui = new GUI();

        // Act
        gui.AdjustHFNCFlowRate(30);

        // Assert
        Assert.Equal(30, gui.HFNCFlowRate);
    }
}
